```typescript
// src/hooks.server.ts
import { redirect, type Handle } from '@sveltejs/kit';

const API_KEY = process.env.API_KEY || '';

export const handle: Handle = async ({ event, resolve }) => {
  if (event.url.pathname.startsWith('/chat') || 
      event.url.pathname.startsWith('/api/') ||
      event.url.pathname.startsWith('/obsidian') ||
      event.url.pathname.startsWith('/notes')) {
    const apiKey = event.request.headers.get('X-API-Key');
    if (!apiKey || apiKey !== API_KEY) {
      return new Response(JSON.stringify({ error: 'Unauthorized' }), { status: 401 });
    }
  }
  return resolve(event);
};
```

Validate and sanitize the filename before writing. Use path.basename() to strip directory components, validate filename format (alphanumeric + safe chars only), and reject suspicious paths. Example:

```typescript
import { basename, join, resolve } from 'path';
import { writeFile } from 'fs/promises';

export const POST: RequestHandler = async ({ request }) => {
  try {
    const { filename, content } = await request.json();

    // Validate inputs
    if (!filename || !content) {
      return json({ error: 'Missing required fields' }, { status: 400 });
    }

    // Sanitize filename - use only the basename, reject path traversal
    const sanitized = basename(filename);
    if (!sanitized || sanitized !== filename) {
      return json({ error: 'Invalid filename' }, { status: 400 });
    }

    // Validate filename format (alphanumeric, dash, underscore, dot only)
    if (!/^[a-zA-Z0-9._-]+$/.test(sanitized)) {
      return json({ error: 'Filename contains invalid characters' }, { status: 400 });
    }

    // Validate content size (e.g., max 1MB)
    if (content.length > 1024 * 1024) {
      return json({ error: 'Content too large' }, { status: 413 });
    }

    const inboxPath = resolve(join(__dirname, '...', 'myfiles', 'inbox'), sanitized);

    // Double-check the resolved path is within inbox directory
    const expectedBase = resolve(join(__dirname, '...', 'myfiles', 'inbox'));
    if (!inboxPath.startsWith(expectedBase)) {
      return json({ error: 'Invalid path' }, { status: 400 });
    }

    await writeFile(inboxPath, content, 'utf-8');
    return json({ success: true, filename: sanitized });
  } catch (error) {
    return json({ error: '...' }, { status: 500 });
  }
};
```

