Avoid shell execution entirely. Use Node.js filesystem APIs directly instead of shelling out. Example:

```typescript
import { json } from '@sveltejs/kit';
import type { RequestHandler } from './$types';
import { writeFile, mkdir } from 'fs/promises';
import { join, resolve, basename } from 'path';

export const POST: RequestHandler = async ({ request }) => {
  try {
    const body = await request.json() as ObsidianRequest;

    // Validate inputs
    if (!body.pattern || !body.noteName || !body.content) {
      return json({ error: 'Missing required fields' }, { status: 400 });
    }

    // Sanitize noteName - prevent path traversal
    const sanitizedName = basename(body.noteName);
    if (!sanitizedName || !/^[a-zA-Z0-9._-]+$/.test(sanitizedName)) {
      return json({ error: 'Invalid note name' }, { status: 400 });
    }

    // Validate content size
    if (body.content.length > 10 * 1024 * 1024) {
      return json({ error: 'Content too large' }, { status: 413 });
    }

    // Use proper path resolution
    const obsidianDir = resolve('myfiles/Fabric_obsidian');
    const fileName = `${new Date().toISOString().split('T')[0]}-${sanitizedName}.md`;
    const filePath = join(obsidianDir, fileName);

    // Ensure resolved path is within obsidianDir
    if (!resolve(filePath).startsWith(obsidianDir)) {
      return json({ error: 'Invalid path' }, { status: 400 });
    }

    // Create directory and write file using Node.js APIs
    await mkdir(obsidianDir, { recursive: true });
    const formattedContent = `\`\`\`markdown\n${body.content}\n\`\`\``;
    await writeFile(filePath, formattedContent, 'utf-8');

    return json({
      success: true,
      fileName,
      filePath,
      message: `Successfully saved to ${fileName}`
    });
  } catch (error) {
    return json({ error: '...' }, { status: 500 });
  }
};
```

