1. Never store tokens in .env files on disk. Use environment variables exclusively or secure credential storage (e.g., OS keychain, HashiCorp Vault).
2. Never log or print token values. Mask sensitive fields in logs.
3. If .env loading is necessary, restrict file permissions to 0600 (owner read-write only):

```go
// In main.go
if exePath, err := os.Executable(); err == nil {
  envPath := filepath.Join(filepath.Dir(exePath), ".env")
  if _, err := os.Stat(envPath); err == nil {
    // Check file permissions before loading
    fi, err := os.Stat(envPath)
    if err != nil {
      fmt.Fprintf(os.Stderr, "Warning: Cannot stat .env file: %v\n", err)
    } else if mode := fi.Mode(); mode.Perm() != 0600 {
      fmt.Fprintf(os.Stderr, "Warning: .env file has overly permissive permissions %o (expected 0600). Token may be exposed.\n", mode.Perm())
    }

    if err := godotenv.Load(envPath); err != nil {
      fmt.Fprintf(os.Stderr, "Warning: Failed to load .env file: %v\n", err)
    }
  }
}

// In token.go - do not print token values
func GetTokenFromEnv(tokenValue string) string {
  if tokenValue == "" {
    tokenValue = os.Getenv("GITHUB_TOKEN")
    if tokenValue == "" {
      tokenValue = os.Getenv("GH_TOKEN")
    }
  }
  // Never return or print the token - return a masked version for logging
  return tokenValue
}

// Helper to mask tokens in logs
func MaskToken(token string) string {
  if len(token) < 8 {
    return "***"
  }
  return token[:4] + "****" + token[len(token)-4:]
}
```

4. Use environment variables only: `export GITHUB_TOKEN=...` rather than storing in files.
5. Rotate tokens regularly and use fine-grained personal access tokens with minimal scopes.

