3. Implement authentication to ensure users can only access their own sessions.
4. Example changes:

```typescript
// In session-store.ts
export const sessionAPI = {
  async loadSessions() {
    try {
      // Retrieve CSRF token from meta tag or cookie
      const csrfToken = document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '';

      const response = await fetch(`/api/sessions/names`, {
        headers: {
          'X-CSRF-Token': csrfToken,
          'X-API-Key': sessionStorage.getItem('apiKey') || '' // If using API key auth
        }
      });
      if (!response.ok) throw new Error(`Failed: ${response.status}`);
      const sessionNames: string[] = await response.json();
      sessions.set(sessionNames.map(name => ({ Name: name, Message: [], Session: '' })));
    } catch (error) {
      console.error('Failed to load sessions:', error);
      sessions.set([]);
    }
  },

  async loadSessionMessages(sessionName: string) {
    try {
      const csrfToken = document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '';

      const response = await fetch(`/api/sessions/${encodeURIComponent(sessionName)}`, {
        headers: {
          'X-CSRF-Token': csrfToken,
          'X-API-Key': sessionStorage.getItem('apiKey') || ''
        }
      });
      if (!response.ok) {
        if (response.status === 403) throw new Error('Access denied to this session');
        throw new Error(`Failed: ${response.status}`);
      }
      return await response.json();
    } catch (error) {
      console.error(`Error loading session ${sessionName}:`, error);
      throw error;
    }
  }
};
```

