Validate and sanitize all user inputs before forwarding to backend:

```typescript
export const POST: RequestHandler = async ({ request }) => {
  try {
    const body = await request.json();

    // Validate request size (max 2MB)
    if (request.headers.get('content-length')) {
      const contentLength = parseInt(request.headers.get('content-length') || '0');
      if (contentLength > 2 * 1024 * 1024) {
        return json({ error: 'Request too large' }, { status: 413 });
      }
    }

    // Validate structure
    if (!body || typeof body !== 'object') {
      return json({ error: 'Invalid request body' }, { status: 400 });
    }

    // Validate prompts if present
    if (body.prompts && Array.isArray(body.prompts)) {
      for (const prompt of body.prompts) {
        if (prompt.userInput && typeof prompt.userInput === 'string') {
          if (prompt.userInput.length > 10000) {
            return json({ error: 'User input too long (max 10000 chars)' }, { status: 400 });
          }
          // Check for null bytes
          if (prompt.userInput.includes('\0')) {
            return json({ error: 'Invalid input' }, { status: 400 });
          }
        }
        if (prompt.patternName && typeof prompt.patternName === 'string') {
          // Validate pattern name format (alphanumeric, underscore, dash only)
          if (!/^[a-zA-Z0-9_-]+$/.test(prompt.patternName)) {
            return json({ error: 'Invalid pattern name' }, { status: 400 });
          }
        }
      }
    }

    // Validate messages if present
    if (body.messages && Array.isArray(body.messages)) {
      if (body.messages.length > 100) {
        return json({ error: 'Too many messages' }, { status: 400 });
      }
      for (const msg of body.messages) {
        if (msg.content && typeof msg.content === 'string') {
          if (msg.content.length > 50000) {
            return json({ error: 'Message too long' }, { status: 400 });
          }
        }
      }
    }

    // Forward validated request
    const fabricResponse = await fetch('http://localhost:8080/api/chat', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    });
    // ... rest of handler
  } catch (error) {
    return json({ error: '...' }, { status: 500 });
  }
};
```

