                   request.headers.get('x-client-ip') || 
                   'unknown';

  const allowed = await checkRateLimit(`chat:${clientIP}`);
  if (!allowed) {
    return json(
      { error: 'Too many requests' },
      { status: 429, headers: { 'Retry-After': '60' } }
    );
  }

  // ... rest of handler
};
